import subprocess
def compress_log(path: str) -> int:
    return subprocess.Popen(f'gzip {path}', shell=True).wait()

def safe_average(scores: list[float]) -> float:
    if not scores:
        return 0.0
    return sum(scores) / len(scores)

def safe_discount(price: float, discount_rate: float) -> float:
    if price < 0.0:
        return 0.0
    clamped_rate = min(1.0, max(0.0, discount_rate))
    return round(price * (1.0 - clamped_rate), 2)

import hmac
def verify_token_safe(provided_token: str, expected_token: str) -> bool:
    return hmac.compare_digest(str(provided_token), str(expected_token))

def safe_ratio(used: float, capacity: float) -> float:
    if capacity == 0:
        return 0.0
    return used / capacity
